"""Order totals for the shop. Amounts are whole cents (int).

All amounts are computed exactly in decimal before being rounded to whole
cents using a single rounding rule: an exact half rounds up.
"""

import decimal


def _percent_to_decimal(percent):
    """Coerce a percentage given as int, float or Decimal into a Decimal.

    A float is read as its usual decimal notation, so ``8.25`` means exactly
    8.25 percent (not its binary approximation).
    """
    if isinstance(percent, decimal.Decimal):
        return percent
    if isinstance(percent, float):
        return decimal.Decimal(str(percent))
    return decimal.Decimal(percent)


def _round_to_cents(amount):
    """Round a Decimal amount to whole cents, halves rounding up."""
    return int(amount.quantize(decimal.Decimal("1"), rounding=decimal.ROUND_HALF_UP))


def line_total(unit_price_cents, quantity, discount_percent=0):
    """Price of one order line in cents after the percentage discount."""
    price = decimal.Decimal(unit_price_cents) * decimal.Decimal(quantity)
    discount = _percent_to_decimal(discount_percent)
    factor = (decimal.Decimal(100) - discount) / decimal.Decimal(100)
    return _round_to_cents(price * factor)


def tax(amount_cents, rate_percent):
    """Tax on an amount, in cents."""
    rate = _percent_to_decimal(rate_percent)
    amount = decimal.Decimal(amount_cents) * rate / decimal.Decimal(100)
    return _round_to_cents(amount)


def order_total(lines, tax_rate_percent=0, shipping_cents=0):
    """Total of an order.

    `lines` is a list of (unit_price_cents, quantity, discount_percent).
    The total is the sum of the line totals, the tax on that sum, and shipping.
    """
    subtotal = sum(line_total(*line) for line in lines)
    return subtotal + tax(subtotal, tax_rate_percent) + shipping_cents


def split_evenly(total_cents, parts):
    """Split a total into `parts` shares that add up to exactly `total_cents`.

    Shares differ by at most one cent, with the larger shares coming first.
    `parts` below one raises ValueError.
    """
    if parts < 1:
        raise ValueError("parts must be at least 1")
    base = total_cents // parts
    remainder = total_cents % parts
    return [base + 1] * remainder + [base] * (parts - remainder)
